/** A module function minus its leading context parameter. */
export type Op<F> = F extends (tview: ToolViewCtx, ...a: infer A) => infer R ? (...a: A) => R : never;

/** Bind a module function to one context so it can be passed around as a value. */
export function bindOp<F extends (tview: ToolViewCtx, ...a: never[]) => unknown>(tview: ToolViewCtx, f: F): Op<F> {
  return ((...a: never[]) => f(tview, ...a)) as Op<F>;
}
